```smithy
$version: "2.0"

// ============================================================================
// contract: ListProducts
// A single, transport-neutral description of one piece of product
// functionality. Nothing in the normative part of this file names HTTP,
// a CLI, or a queue. The same model is served over an RPC endpoint,
// invoked as a terminal command, or executed by a background worker.
// ============================================================================

metadata "contract" = {
    id: "com.example.catalog#ListProducts"
    revision: "2026-07-31"
    stability: "stable"
    transportNeutral: true
    consistency: "read-your-writes not guaranteed; snapshot may shift between pages"
}

// Non-normative. Adapters MAY use these hints; generators MUST NOT treat
// them as part of the contract, and a transport that ignores them is still
// conformant.
metadata "transportHints" = {
    note: "Illustrative bindings only. The normative contract is the model below."
    rpcOverHttp: {
        method: "GET"
        path: "/v1/products"
        statusByError: {
            "UnauthenticatedError": 401
            "PermissionDeniedError": 403
            "ValidationError": 400
            "InvalidPageTokenError": 400
            "ThrottledError": 429
            "InternalError": 500
        }
    }
    commandLine: {
        command: "catalog products list"
        flags: ["--name-query", "--page-size", "--page-token"]
        exitCodeByCategory: { "client": 2, "throttling": 75, "server": 70 }
    }
    backgroundJob: {
        invocation: "worker consumes an input document and emits an output document"
        pagination: "worker loops on nextPageToken until it is absent"
    }
}

namespace com.example.catalog

// ----------------------------------------------------------------------------
// Authorization requirement, expressed as data rather than as a transport
// mechanism. The caller identity is ambient context supplied by the adapter
// (bearer token, OS user, job principal); it is deliberately NOT an input
// member, so no transport's credential format leaks into the contract.
// ----------------------------------------------------------------------------

/// The operation may only be executed on behalf of an authenticated principal
/// that holds the named permission. How the principal is established and
/// conveyed is the adapter's concern.
@trait(selector: "operation")
structure requiresAuthenticatedCaller {
    /// Permission the resolved principal must hold.
    @required
    permission: String

    /// Behaviour when no principal can be resolved.
    @required
    onMissingIdentity: String

    /// Behaviour when a principal is resolved but lacks the permission.
    @required
    onInsufficientPermission: String
}

@title("Product Catalog")
service ProductCatalog {
    version: "2026-07-31"
    operations: [ListProducts]
}

// ----------------------------------------------------------------------------
// Operation
// ----------------------------------------------------------------------------

/// Returns a page of products visible to the calling principal, optionally
/// narrowed to those whose name matches a search term.
///
/// Ordering is stable and deterministic: ascending by `name`, then ascending
/// by `productId` as a tie-break. Callers may rely on this ordering to page
/// without duplicates for items that are not concurrently renamed.
///
/// The operation has no side effects and may be retried freely.
@readonly
@requiresAuthenticatedCaller(
    permission: "catalog.products.list"
    onMissingIdentity: "fail with UnauthenticatedError"
    onInsufficientPermission: "fail with PermissionDeniedError"
)
@paginated(
    inputToken: "pageToken"
    outputToken: "nextPageToken"
    pageSize: "pageSize"
    items: "products"
)
operation ListProducts {
    input := {
        /// Optional case-insensitive substring match against the product name.
        /// Omitted or absent means "no name filtering". An empty string is a
        /// validation failure, not a synonym for "no filter".
        nameQuery: NameQuery

        /// Maximum number of items the caller is willing to receive.
        /// The service may return fewer, even when more pages exist.
        @default(25)
        pageSize: PageSize

        /// Opaque continuation token from a previous response. Must be echoed
        /// back byte-for-byte. Absent on the first call. Callers must not
        /// parse, construct, or persist tokens beyond their validity window.
        pageToken: PageToken
    }

    output := {
        /// Items in this page, in the ordering described above. May be empty:
        /// an empty list with a `nextPageToken` present is legal.
        @required
        products: ProductSummaryList

        /// Present if and only if more results may exist. Absence is the only
        /// authoritative signal that iteration is complete.
        nextPageToken: PageToken

        /// Best-effort count of all matching items. Advisory only: it may be
        /// stale, may change between pages, and must not be used to decide
        /// when to stop paging.
        estimatedTotalCount: Long
    }

    errors: [
        UnauthenticatedError
        PermissionDeniedError
        ValidationError
        InvalidPageTokenError
        ThrottledError
        InternalError
    ]
}

// ----------------------------------------------------------------------------
// Payload shapes
// ----------------------------------------------------------------------------

@length(min: 1, max: 200)
string NameQuery

@range(min: 1, max: 100)
integer PageSize

@length(min: 1, max: 2048)
string PageToken

@length(min: 1, max: 64)
string ProductId

/// ISO 4217 alphabetic currency code.
@pattern("^[A-Z]{3}$")
string CurrencyCode

list ProductSummaryList {
    member: ProductSummary
}

/// The projection of a product returned by list operations. Deliberately
/// narrower than the full product record; callers needing more must fetch
/// the product individually.
structure ProductSummary {
    @required
    productId: ProductId

    @required
    name: String

    @required
    status: ProductStatus

    /// Price in the smallest indivisible unit of `priceCurrency`
    /// (for example, cents). Integer to avoid decimal representation drift
    /// across languages and transports.
    @required
    priceAmountMinor: Long

    @required
    priceCurrency: CurrencyCode

    /// Instant of the last modification, as an absolute point in time.
    /// No wire encoding is implied here.
    @required
    updatedAt: Timestamp
}

enum ProductStatus {
    ACTIVE
    INACTIVE
    DISCONTINUED
}

// ----------------------------------------------------------------------------
// Failure modes
//
// This list is exhaustive: a conformant implementation fails only in these
// ways. Each shape name is the stable, machine-comparable failure code.
// ----------------------------------------------------------------------------

/// No authenticated principal could be resolved for the invocation.
/// The caller is not signed in, or the credential is expired or unreadable.
/// Not retryable without new credentials.
@error("client")
structure UnauthenticatedError {
    @required
    message: String
}

/// A principal was resolved but does not hold `catalog.products.list`.
/// Retrying with the same identity will not succeed.
@error("client")
structure PermissionDeniedError {
    @required
    message: String

    /// Permission that was required but absent.
    @required
    requiredPermission: String
}

/// One or more input members violated the declared constraints
/// (for example, `pageSize` out of range, or an empty `nameQuery`).
@error("client")
structure ValidationError {
    @required
    message: String

    @required
    fieldViolations: FieldViolationList
}

list FieldViolationList {
    member: FieldViolation
}

structure FieldViolation {
    /// Dotted path to the offending input member, e.g. "pageSize".
    @required
    path: String

    @required
    reason: ViolationReason

    @required
    message: String
}

enum ViolationReason {
    REQUIRED
    OUT_OF_RANGE
    TOO_LONG
    TOO_SHORT
    MALFORMED
    UNSUPPORTED_VALUE
}

/// The supplied `pageToken` is malformed, expired, or was issued for a
/// different query. Recover by restarting iteration from the first page;
/// resubmitting the same token will keep failing.
@error("client")
structure InvalidPageTokenError {
    @required
    message: String
}

/// The caller exceeded its request allowance. Retryable after a delay.
@error("client")
@retryable(throttling: true)
structure ThrottledError {
    @required
    message: String

    /// Suggested minimum delay before retrying, in seconds.
    retryAfterSeconds: Integer
}

/// The service failed for a reason the caller cannot correct. Safe to retry
/// with backoff, because the operation has no side effects.
@error("server")
@retryable
structure InternalError {
    @required
    message: String

    /// Opaque identifier the caller can quote when reporting the failure.
    correlationId: String
}
```

I chose Smithy because it is one of the few interface definition languages whose core model contains no transport at all — operations, errors, and pagination are modelled as data, so the same file describes an RPC endpoint, a CLI command, and a worker invocation without rewriting. It is genuinely machine readable: the IDL has a formal grammar and a normative JSON AST, with official code generators for TypeScript, Python, Java, Kotlin, Rust, and Go. Errors are first-class shapes with client/server and retryability semantics rather than HTTP status codes, which is exactly what a background job needs in order to decide whether to retry. Transport specifics that consumers still want are confined to a `metadata` block that is explicitly non-normative, keeping the contract itself neutral.
